-- Тема 17: варианты ответов выровнены по длине и форме (71 исправлений в 23 вопросах), ключи не меняются.
-- Источник: scripts/questions/088_option_length_topic17.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Чем физическая резервная копия отличается от логической (дампа)?', 'Физическая — копия файлов кластера и журналов WAL, логическая — команды SQL для воссоздания объектов', 'Физическая — копия файлов и WAL, логическая — команды SQL', 'Поэтому физическая восстанавливается быстро, а при наличии архива WAL — и на любой момент после окончания её создания; логическая гибче.', 'Физическая — копия файлов кластера и журналов WAL, логическая — команды SQL для воссоздания объектов. Поэтому физическая восстанавливается быстро, а при наличии архива WAL — и на любой момент после окончания её создания; логическая гибче.'),
        ('option', 'Чем физическая резервная копия отличается от логической (дампа)?', 'Логическая копия всегда быстрее восстанавливается', 'Логическая копия восстанавливается быстрее, чем физическая', NULL, NULL),
        ('option', 'Чем физическая резервная копия отличается от логической (дампа)?', 'Физическая копия делается только при остановленном сервере', 'Физическая копия содержит команды SQL, логическая — файлы', 'Физическую копию можно снять и на работающем сервере, например pg_basebackup.', 'Наоборот: физическая — копия файлов кластера, логическая — команды SQL.'),
        ('option', 'Мешает ли работающий pg_dump другим сеансам?', 'Никак не мешает, блокировок не берёт', 'Никак не мешает: блокировок он не берёт', NULL, NULL),
        ('option', 'Мешает ли работающий pg_dump другим сеансам?', 'Чтение и изменение данных не блокируются, но DROP TABLE и большинство форм ALTER TABLE для выгружаемых таблиц будут ждать', 'Чтение и запись идут, но DROP и ALTER TABLE ждут', 'pg_dump берёт блокировки ACCESS SHARE и держит их до конца выгрузки.', 'Чтение и изменение данных не блокируются, но DROP TABLE и большинство форм ALTER TABLE для выгружаемых таблиц будут ждать: pg_dump берёт блокировки ACCESS SHARE и держит их до конца выгрузки.'),
        ('option', 'Мешает ли работающий pg_dump другим сеансам?', 'Блокирует всю базу на запись до конца выгрузки', 'Блокирует всю базу на запись до конца выгрузки дампа', NULL, NULL),
        ('option', 'Чем горячее физическое резервное копирование файлов кластера отличается от холодного?', 'Горячее копирование возможно только для логических копий', 'Горячее копирование берёт файлы кластера без журналов WAL', 'Физическая копия тоже снимается горячей, например pg_basebackup.', 'Горячей копии как раз нужны журналы WAL за время копирования.'),
        ('option', 'Чем горячее физическое резервное копирование файлов кластера отличается от холодного?', 'Горячее делается на работающем сервере, и для восстановления нужны журналы WAL за время копирования', 'Делается на работающем сервере, нужен WAL за это время', NULL, NULL),
        ('option', 'Чем горячее физическое резервное копирование файлов кластера отличается от холодного?', 'Холодная копия всегда требует архива журналов', 'Холодной копии нужен архив журналов WAL', NULL, NULL),
        ('option', 'Что делает в PostgreSQL команда ALTER DATABASE … BEGIN BACKUP?', 'Такой команды в PostgreSQL нет, это синтаксис Oracle', 'Такой команды нет, это синтаксис Oracle', NULL, NULL),
        ('option', 'Что важно при низкоуровневом копировании через pg_backup_start в PostgreSQL 16?', 'Между вызовами нельзя подключаться к серверу', 'Между вызовами к серверу нельзя подключаться другим сеансам', NULL, NULL),
        ('option', 'Что важно при низкоуровневом копировании через pg_backup_start в PostgreSQL 16?', 'Сеанс, вызвавший pg_backup_start, должен оставаться открытым до pg_backup_stop', 'Сеанс с pg_backup_start должен жить до pg_backup_stop', 'Если соединение прервётся, копирование будет отменено.', 'Сеанс, вызвавший pg_backup_start, должен оставаться открытым до pg_backup_stop: если соединение прервётся, копирование будет отменено.'),
        ('option', 'Что важно при низкоуровневом копировании через pg_backup_start в PostgreSQL 16?', 'Сервер нужно перевести в режим только для чтения', 'Сервер нужно перевести в режим без записи', NULL, NULL),
        ('option', 'Что нужно для восстановления кластера на момент в прошлом (PITR)?', 'Только базовая копия', 'Базовая копия без архива журналов', NULL, NULL),
        ('option', 'Что нужно для восстановления кластера на момент в прошлом (PITR)?', 'Базовая копия и непрерывный архив WAL от её начала до нужного момента', 'Базовая копия и непрерывный архив WAL до цели', 'Журнал применяется к копии до целевой точки.', 'Нужны базовая копия и непрерывный архив WAL от её начала до нужного момента: журнал применяется к копии до целевой точки.'),
        ('option', 'Что нужно для восстановления кластера на момент в прошлом (PITR)?', 'Только архив WAL', 'Архив WAL без какой-либо базовой копии', NULL, NULL),
        ('option', 'Что нужно для восстановления кластера на момент в прошлом (PITR)?', 'Только дамп pg_dump', 'Свежий дамп pg_dump на нужный момент', NULL, NULL),
        ('option', 'Что по умолчанию делает сервер, достигнув целевой точки восстановления?', 'Приостанавливает восстановление, чтобы можно было проверить данные', 'Ставит восстановление на паузу для проверки', NULL, NULL),
        ('option', 'Что по умолчанию делает сервер, достигнув целевой точки восстановления?', 'Удаляет архив журналов', 'Удаляет использованные сегменты архива журналов', NULL, NULL),
        ('option', 'Что по умолчанию делает сервер, достигнув целевой точки восстановления?', 'Сразу становится обычным сервером', 'Сразу становится обычным сервером для записи', NULL, NULL),
        ('option', 'Можно ли восстановиться из базовой копии на момент раньше окончания её создания?', 'Нет: целевая точка должна быть после окончания копирования, нужна более ранняя копия', 'Нет: цель должна быть позже конца копирования', 'Раньше этого момента копия ещё несогласованна.', 'Целевая точка должна быть после окончания копирования: раньше этого момента копия ещё несогласованна; нужна более ранняя копия.'),
        ('option', 'Можно ли восстановиться из базовой копии на момент раньше окончания её создания?', 'Да, если указать recovery_target_lsn', 'Да, если указать в настройках recovery_target_lsn', NULL, NULL),
        ('option', 'Можно ли восстановиться из базовой копии на момент раньше окончания её создания?', 'Да, но только для отдельной базы', 'Да, если восстанавливать отдельную базу', NULL, NULL),
        ('option', 'Можно ли восстановиться из базовой копии на момент раньше окончания её создания?', 'Да, на любой момент из архива', 'Да, на любой момент, который есть в архиве', NULL, NULL),
        ('option', 'Почему высокий buffer hit ratio не означает, что остальные блоки читались с диска?', 'Блоки из blks_read могли быть взяты из кеша операционной системы', 'Блоки blks_read могли прийти из кеша ОС', 'PostgreSQL не знает, читала ли ОС блок с диска или из своего кеша.', 'PostgreSQL не знает, читала ли ОС блок с диска или из своего кеша: блоки из blks_read могли быть взяты из кеша операционной системы.'),
        ('option', 'Почему высокий buffer hit ratio не означает, что остальные блоки читались с диска?', 'blks_read учитывает только временные файлы', 'blks_read учитывает временные файлы, а не таблицы', NULL, NULL),
        ('option', 'Почему высокий buffer hit ratio не означает, что остальные блоки читались с диска?', 'buffer hit ratio всегда равен 100%', 'Счётчики не учитывают чтения индексов', 'Нет, он зависит от нагрузки и размера кеша.', 'Счётчики базы учитывают чтения и таблиц, и индексов.'),
        ('option', 'Чем опасны сеансы в состоянии idle in transaction?', 'Они ничем не опасны', 'Они ничем не опасны для сервера', NULL, NULL),
        ('option', 'Чем опасны сеансы в состоянии idle in transaction?', 'Они потребляют много процессорного времени', 'Они потребляют много процессорного времени сервера', NULL, NULL),
        ('option', 'Чем опасны сеансы в состоянии idle in transaction?', 'Они удерживают блокировки и могут удерживать горизонт очистки', 'Держат блокировки и могут удерживать горизонт', 'Таблицы растут, а другие сеансы ждут блокировок.', 'Они удерживают блокировки и могут удерживать горизонт очистки: таблицы растут, а другие сеансы ждут блокировок.'),
        ('option', 'Какие системы используют для мониторинга PostgreSQL?', 'pg_upgrade', 'pg_upgrade с ключом --check', 'Это утилита обновления основной версии.', 'Это утилита обновления основной версии; --check лишь проверяет совместимость кластеров.'),
        ('option', 'Какие системы используют для мониторинга PostgreSQL?', 'Zabbix', 'Zabbix с шаблоном PostgreSQL', NULL, NULL),
        ('option', 'Какие системы используют для мониторинга PostgreSQL?', 'pgbench', 'pgbench с ключом --progress', 'Это утилита нагрузочного тестирования.', 'Это утилита нагрузочного тестирования; --progress показывает ход теста, а не мониторит сервер.'),
        ('option', 'Что гарантирует synchronous_commit = remote_write при синхронной реплике?', 'Реплика получила записи и передала их ОС, но на диск они ещё могут быть не сброшены', 'Реплика получила записи и передала их ОС', 'Данные переживут сбой процесса PostgreSQL на реплике; при сбое её ОС сохранность не гарантируется, поскольку запись на устойчивый носитель могла ещё не завершиться.', 'Реплика получила записи и передала их ОС, но на диск они ещё могут быть не сброшены: данные переживут сбой процесса PostgreSQL на реплике, но не сбой её ОС.'),
        ('option', 'Что гарантирует synchronous_commit = remote_write при синхронной реплике?', 'Реплику не ждут', 'Фиксация не ждёт синхронную реплику', NULL, NULL),
        ('option', 'Что гарантирует synchronous_commit = remote_write при синхронной реплике?', 'Записи сброшены на диск реплики', 'Записи надёжно сброшены на диск синхронной реплики', NULL, NULL),
        ('option', 'Что гарантирует synchronous_commit = remote_write при синхронной реплике?', 'Записи применены на реплике', 'Записи уже применены на реплике и видны запросам', NULL, NULL),
        ('option', 'Что будет при synchronous_commit = off и сбое сервера?', 'Могут потеряться последние подтверждённые транзакции, но согласованность базы не нарушится', 'Могут пропасть последние транзакции, база цела', 'Фиксация не ждёт записи журнала на диск.', 'Могут потеряться последние подтверждённые транзакции, но согласованность базы не нарушится: фиксация не ждёт записи журнала на диск.'),
        ('option', 'Что будет при synchronous_commit = off и сбое сервера?', 'Ничего не потеряется', 'Ничего не потеряется, фиксация надёжна', NULL, NULL),
        ('option', 'Что будет при synchronous_commit = off и сбое сервера?', 'База может быть повреждена', 'База может оказаться повреждённой после такого сбоя', NULL, NULL),
        ('option', 'Какие значения synchronous_commit заставляют фиксацию ждать синхронную реплику?', '`remote_apply`', '`synchronous_commit = remote_apply`', NULL, NULL),
        ('option', 'Какие значения synchronous_commit заставляют фиксацию ждать синхронную реплику?', '`remote_write`', '`synchronous_commit = remote_write`', NULL, NULL),
        ('option', 'Какие значения synchronous_commit заставляют фиксацию ждать синхронную реплику?', '`local`', '`synchronous_commit = local`', NULL, NULL),
        ('option', 'Какие значения synchronous_commit заставляют фиксацию ждать синхронную реплику?', '`on`', '`synchronous_commit = on`', NULL, NULL),
        ('option', 'Что верно для свойств ACID?', 'Атомарность: изменения транзакции применяются целиком или не применяются вовсе', 'Атомарность: транзакция применяется целиком или никак', NULL, NULL),
        ('option', 'Что верно для свойств ACID?', 'Изолированность: транзакции всегда выполняются строго по очереди', 'Изолированность: транзакции выполняются строго по очереди', NULL, NULL),
        ('option', 'Что будет с таблицей, созданной внутри транзакции, если выполнить ROLLBACK?', 'Её не будет: CREATE TABLE, как и большинство команд DDL в PostgreSQL, транзакционна', 'Её не будет: CREATE TABLE транзакционна', 'Это отличает PostgreSQL от многих других СУБД.', 'CREATE TABLE, как и большинство команд DDL в PostgreSQL, транзакционна; это отличает PostgreSQL от многих других СУБД.'),
        ('option', 'Что будет с таблицей, созданной внутри транзакции, если выполнить ROLLBACK?', 'Таблица останется, откатятся только данные', 'ROLLBACK завершится ошибкой из-за выполненного DDL', 'Создание таблицы тоже откатывается.', 'ROLLBACK отменяет и команды DDL, ошибки нет.'),
        ('option', 'Что будет с таблицей, созданной внутри транзакции, если выполнить ROLLBACK?', 'Транзакция не начнётся: DDL нельзя выполнять в транзакции', 'DDL вообще нельзя выполнять внутри транзакции', 'Большинство команд DDL можно.', 'Большинство команд DDL можно выполнять в транзакции и откатывать.'),
        ('option', 'Какую команду нельзя выполнить внутри блока транзакции?', '`TRUNCATE`', '`TRUNCATE TABLE`', NULL, NULL),
        ('option', 'Какую команду нельзя выполнить внутри блока транзакции?', '`CREATE TABLE`', '`CREATE TABLE AS`', NULL, NULL),
        ('option', 'Уменьшится ли размер файла таблицы на диске после DELETE и VACUUM?', 'Обычно нет: место станет свободным внутри файла, ОС вернётся только пустой хвост файла', 'Обычно нет: место остаётся внутри файла', 'Освобождённое место используют новые строки этой таблицы.', 'Место станет свободным внутри файла, и его используют новые строки этой таблицы; ОС вернётся только пустой хвост файла.'),
        ('option', 'Уменьшится ли размер файла таблицы на диске после DELETE и VACUUM?', 'Да, сразу после DELETE', 'Да, сразу после выполнения DELETE', NULL, NULL),
        ('option', 'Уменьшится ли размер файла таблицы на диске после DELETE и VACUUM?', 'Да, всегда после VACUUM', 'Да, VACUUM сжимает файл до размера данных', 'VACUUM возвращает ОС только пустые страницы в конце файла.', 'VACUUM возвращает ОС только пустые страницы в конце файла, а не сжимает его до размера данных.'),
        ('option', 'Что нужно учитывать, запуская VACUUM FULL для большой таблицы?', 'Таблица полностью блокируется, и нужно свободное место для её новой копии', 'Таблица блокируется, и нужно место для её копии', 'Таблица и индексы перезаписываются заново.', 'Таблица полностью блокируется (ACCESS EXCLUSIVE), и нужно свободное место для её новой копии: таблица и индексы перезаписываются заново.'),
        ('option', 'Что нужно учитывать, запуская VACUUM FULL для большой таблицы?', 'Таблица остаётся доступной на запись', 'Таблица остаётся доступной для записи', NULL, NULL),
        ('option', 'Чем общий план подготовленного оператора отличается от частного?', 'Частный строится с учётом конкретных значений параметров, общий — без них и используется повторно', 'Частный учитывает значения параметров, общий — нет', 'Общий план экономит время планирования, частный учитывает значения параметров и может оказаться эффективнее.', 'Частный строится с учётом конкретных значений параметров, общий — без них и используется повторно: он экономит время планирования, а частный может оказаться эффективнее.'),
        ('option', 'Чем общий план подготовленного оператора отличается от частного?', 'Частный план хранится на диске', 'Частный план сохраняется на диске сервера', NULL, NULL),
        ('option', 'Чем общий план подготовленного оператора отличается от частного?', 'Разницы нет', 'Разницы нет: это один и тот же план', NULL, NULL),
        ('option', 'Когда при plan_cache_mode = auto подготовленный оператор с параметрами переходит на общий план?', 'После ANALYZE таблицы', 'После выполнения ANALYZE этой таблицы', NULL, NULL),
        ('option', 'Когда при plan_cache_mode = auto подготовленный оператор с параметрами переходит на общий план?', 'После пяти выполнений с частными планами, если общий план не намного дороже их средней стоимости', 'После пяти частных планов, если общий не намного дороже', 'Иначе продолжают строиться частные планы.', 'После пяти выполнений с частными планами, если общий план не намного дороже их средней стоимости; иначе продолжают строиться частные планы.'),
        ('option', 'Когда при plan_cache_mode = auto подготовленный оператор с параметрами переходит на общий план?', 'Сразу при первом выполнении', 'Сразу при первом выполнении оператора', NULL, NULL),
        ('option', 'Когда при plan_cache_mode = auto подготовленный оператор с параметрами переходит на общий план?', 'Никогда', 'Не переходит, пока не задан force_generic_plan', 'Переход возможен после пяти выполнений.', 'Переход возможен после пяти выполнений; force_generic_plan включает общий план сразу.'),
        ('option', 'Как в штатном режиме обновляется статистика для планировщика?', 'При каждой контрольной точке', 'При каждой контрольной точке сервера', NULL, NULL),
        ('option', 'Как в штатном режиме обновляется статистика для планировщика?', 'Только вручную командой ANALYZE', 'Вручную командой ANALYZE администратором', 'Обычно её запускает автоочистка.', 'Обычно её запускает автоочистка; вручную ANALYZE выполняют при необходимости, но это не штатный путь.'),
        ('option', 'Как в штатном режиме обновляется статистика для планировщика?', 'Автоочистка выполняет ANALYZE, когда изменилось достаточно строк таблицы', 'Автоочистка запускает ANALYZE после изменений', 'Порог задают autovacuum_analyze_threshold и autovacuum_analyze_scale_factor.', 'Автоочистка выполняет ANALYZE, когда изменилось достаточно строк таблицы; порог задают autovacuum_analyze_threshold и autovacuum_analyze_scale_factor.'),
        ('option', 'Как в штатном режиме обновляется статистика для планировщика?', 'При каждом выполнении запроса', 'При каждом выполнении запроса к таблице', NULL, NULL),
        ('option', 'Зачем нужна команда CREATE STATISTICS?', 'Посмотреть статистику по таблице', 'Посмотреть собранную статистику по таблице', NULL, NULL),
        ('option', 'Зачем нужна команда CREATE STATISTICS?', 'Собирать расширенную статистику по нескольким столбцам, например их зависимость', 'Собирать статистику по связям нескольких столбцов', 'Обычная статистика считает столбцы независимыми и ошибается для связанных.', 'Собирает расширенную статистику по нескольким столбцам, например их зависимость: обычная статистика считает столбцы независимыми и ошибается для связанных.'),
        ('option', 'Зачем нужна команда CREATE STATISTICS?', 'Включить сбор статистики для таблицы', 'Включить сбор обычной статистики для таблицы', NULL, NULL),
        ('option', 'Зачем нужна команда CREATE STATISTICS?', 'Сбросить накопительную статистику', 'Сбросить накопительную статистику таблицы', NULL, NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
